const captureSource=" class DisposalCapture extends AudioWorkletProcessor{\n  constructor(){super();this.sequence=0;this.previousEnd=null;this.startupGaps=[];this.preflight=null;this.armId=null;this.finishId=null;this.armed=false;this.finished=false;this.port.onmessage=({data})=>{if(data.type==='preflight'&&!this.armed)this.preflight={id:data.id,consecutive:0,previousEnd:null,firstFrame:null};else if(data.type==='arm'&&!this.armed)this.armId=data.id;else if(data.type==='finish')this.finishId=data.id;};this.port.postMessage({type:'ready'});}\n  process(inputs,outputs){outputs[0].forEach(c=>c.fill(0));if(this.finished)return false;const length=outputs[0][0].length,sequence=this.sequence++;if(this.previousEnd!==null&&currentFrame!==this.previousEnd)this.startupGaps.push({expected:this.previousEnd,actual:currentFrame,sequence});this.previousEnd=currentFrame+length;\n   if(this.preflight){const p=this.preflight;if(p.previousEnd===null||currentFrame!==p.previousEnd){p.consecutive=1;p.firstFrame=currentFrame;}else p.consecutive++;p.previousEnd=currentFrame+length;if(p.consecutive>=64){this.port.postMessage({type:'preflight',id:p.id,firstFrame:p.firstFrame,lastFrame:p.previousEnd,consecutive:p.consecutive,startupGaps:this.startupGaps.slice()});this.preflight=null;}}\n   if(!this.armed){if(this.armId===null){if(this.finishId!==null){this.port.postMessage({type:'finished',id:this.finishId,unarmed:true,lastFrame:currentFrame+length,lastSequence:sequence});this.finished=true;return false;}return true;}this.armed=true;this.port.postMessage({type:'armed',id:this.armId,firstFrame:currentFrame,firstSequence:sequence,startupGaps:this.startupGaps.slice()});}\n   const source=inputs[0]||[],channels=[0,1].map(c=>source[c]?.slice()||new Float32Array(length));this.port.postMessage({type:'pcm',sequence,frame:currentFrame,inputChannels:source.length,channels},channels.map(c=>c.buffer));if(this.finishId!==null){this.port.postMessage({type:'finished',id:this.finishId,lastFrame:currentFrame+length,lastSequence:sequence});this.finished=true;return false;}return true;\n  }\n }\n\nregisterProcessor('open-play-live-keylock-capture',DisposalCapture);";
