 function capture(label){const node=new AudioWorkletNode(context,'open-play-live-keylock-capture',{numberOfInputs:1,numberOfOutputs:1,outputChannelCount:[2]}),bus=context.createGain(),blocks=[],waiters=new Map();bus.channelCount=2;bus.channelCountMode='explicit';bus.channelInterpretation='discrete';zero.connect(bus);bus.connect(node);node.connect(safe);let readyResolve,id=0;const target={label,node,bus,blocks,errors:[],ready:new Promise(r=>readyResolve=r)};node.port.onmessage=({data})=>{if(data.type==='ready')readyResolve();else if(data.type==='pcm'){const previous=blocks.at(-1);if(previous&&(data.frame!==previous.frame+previous.channels[0].length||data.sequence!==previous.sequence+1))target.errors.push({previousFrame:previous.frame,actualFrame:data.frame,sequence:data.sequence});blocks.push(data);}else{const resolve=waiters.get(data.id);if(resolve){waiters.delete(data.id);resolve(data);}}};target.request=type=>{const key=label+'-'+type+'-'+(++id);return bounded(new Promise(resolve=>{waiters.set(key,resolve);node.port.postMessage({type,id:key});}),'capture '+key).finally(()=>waiters.delete(key));};captures.push(target);return target;}
