  await check('Actual22050Hz source prepares bounded normalized window and begins at measured output time',async e=>{a=await createLiveKeylock(context,{buffers:[fixture(22050,48)],signal:controller.signal,onEvent:event=>events.push(event)});adapters.push(a);a.outputs[0].connect(single.bus);e.captureReadiness=await Promise.all([arm(single),arm(control)]);const ack=await a.start(),observed=await measured(single,ack.when+.25,.4),begin=Math.max(single.arm.firstFrame/context.sampleRate,ack.when-.1),data=await pcm(single,begin,.4);let onset=null;for(let i=0;i+256<=data.data.length;i+=128){let p=0;for(let k=i;k<i+256;k++)p+=data.data[k]**2;if(Math.sqrt(p/256)>.005){onset=begin+i/context.sampleRate;break;}}Object.assign(e,{ack,observed,onset,onsetMinusRequested:onset===null?null:onset-ack.when,snapshot:a.snapshot()});tone(observed,440);assert(onset!==null&&Math.abs(onset-ack.when)<=.03,'Actual onset outside explicit30ms prototype budget');});
  await check('Same live node1→1.25→.8 preserves pitch and actual source-modulation rate',async e=>{const id=a.snapshot().groups[0].id,measurements=[];for(const rate of[1.25,.8]){const ack=await a.update({rate}),observed=await measured(single,ack.when+.25,1.3);measurements.push({ack,observed});tone(observed,440);assert(Math.abs(observed.envelopeFit.frequency-4*rate)<=.15&&observed.envelopeFit.relativeAmplitude>.08,'Actual source-envelope rate differs');assert(observed.maxBelow005RunMs===0,'Silent gap during held-rate tone');assert(a.snapshot().groups[0].id===id,'Live retime unnecessarily replaced group');}e.measurements=measurements;});
