  const fiveCaptures=[];
  await check('Five actual positional sources retain supplied order and tolerated tail geometry',async e=>{const buffers=[fixture(22050,12,330,false),...Array.from({length:4},(_,i)=>fixture(context.sampleRate,11.95,440+i*110,false))];five=await createLiveKeylock(context,{buffers,signal:fiveOwner.signal});adapters.push(five);for(let i=0;i<5;i++){const captureTarget=capture('positional-'+i);fiveCaptures.push(captureTarget);five.outputs[i].connect(captureTarget.bus);}e.readiness=await Promise.all(fiveCaptures.map(arm));const ack=await five.start(),observed=await Promise.all(fiveCaptures.map(c=>measured(c,ack.when+.25))),snapshot=five.snapshot();observed.forEach((m,i)=>tone(m,[330,440,550,660,770][i]));assert(snapshot.sourceGeometry.slice(1).every(g=>Math.abs(g.paddedTailSeconds-.05)<1e-9),'Prepared tolerance geometry lost');Object.assign(e,{ack,observed,snapshot});});
